import assert from"node:assert/strict";import{readFileSync}from"node:fs";import test from"node:test";const source=readFileSync(new URL("../src/design/PrototypeCollaborationStudio.jsx",import.meta.url),"utf8");test("prototype builder persists screens interactions variables and versions",()=>{for(const call of ["createPrototype","updatePrototype","listPrototypeVersions"])assert.match(source,new RegExp(`api\\.${call}`));for(const item of ["Click","Hover","Focus","Drag","Conditional","Form validation","Smart transition"])assert.match(source,new RegExp(item));});test("collaboration uses durable comments, polling presence and governed sharing",()=>{assert.match(source,/api\.listComments/);assert.match(source,/api\.createComment/);assert.match(source,/setInterval\(reload,5000\)/);assert.match(source,/Share governed link/);});test("version restoration preserves later history by creating a version",()=>{assert.match(source,/Restore as new version/);assert.match(source,/later history is retained/);});
